from typing import List
class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(profits)
        ans = -1
        for j in range(1, n - 1):
            l = r = 0
            for i in range(j):
                if prices[i] < prices[j]:
                    l = max(l, profits[i])
            for k in range(j + 1, n):
                if prices[k] > prices[j]:
                    r = max(r, profits[k])
            if l and r:
                ans = max(ans, l + profits[j] + r)
        return ans

