from typing import List
class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(profits)
        vals = sorted(set(prices)); m = len(vals)
        rk = {v: i + 1 for i, v in enumerate(vals)}
        def calc(ps, fs):
            tree = [0] * (m + 1)
            res = [0] * len(ps)
            for j in range(len(ps)):
                i, b = rk[ps[j]] - 1, 0
                while i > 0:
                    b = max(b, tree[i]); i -= i & -i
                res[j] = b
                i = rk[ps[j]]
                while i <= m:
                    if tree[i] < fs[j]: tree[i] = fs[j]
                    i += i & -i
            return res
        left = calc(prices, profits)
        right = calc(prices[::-1], profits[::-1])[::-1]
        ans = -1
        for j in range(n):
            if left[j] and right[j]:
                ans = max(ans, left[j] + profits[j] + right[j])
        return ans

