class Solution {
    int m;
    vector<int> tree;
    void upd(int i, int v) { for (; i <= m; i += i & -i) tree[i] = max(tree[i], v); }
    int qry(int i) { int r = 0; for (; i > 0; i -= i & -i) r = max(r, tree[i]); return r; }
public:
    int maxProfit(vector<int>& prices, vector<int>& profits) {
        int n = profits.size();
        vector<int> vals = prices;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        m = vals.size();
        auto rk = [&](int p) { return lower_bound(vals.begin(), vals.end(), p) - vals.begin() + 1; };
        auto calc = [&](vector<int> ps, vector<int> fs) {
            tree.assign(m + 1, 0);
            vector<int> res(n);
            for (int j = 0; j < n; j++) {
                res[j] = qry(rk[ps[j]] - 1);
                upd(rk[ps[j]], fs[j]);
            }
            return res;
        };
        vector<int> left = calc(prices, profits);
        reverse(prices.begin(), prices.end());
        reverse(profits.begin(), profits.end());
        vector<int> right = calc(prices, profits);
        reverse(right.begin(), right.end());
        int ans = -1;
        for (int j = 0; j < n; j++)
            if (left[j] && right[j]) ans = max(ans, left[j] + profits[j] + right[j]);
        return ans;
    }
};

