class Solution {
    private int m;
    private int[] tree;
    private void upd(int i, int v) { for (; i <= m; i += i & -i) tree[i] = Math.max(tree[i], v); }
    private int qry(int i) { int r = 0; for (; i > 0; i -= i & -i) r = Math.max(r, tree[i]); return r; }
    public int maxProfit(int[] prices, int[] profits) {
        int n = profits.length;
        int[] vals = prices.clone();
        Arrays.sort(vals);
        m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || vals[i] != vals[i - 1]) vals[m++] = vals[i];
        int[][] pr = new int[n][2];
        for (int i = 0; i < n; i++) pr[i] = new int[]{prices[i], profits[i]};
        java.util.function.BiFunction<int[], Boolean, int[]> calc = (arr, rev) -> {
            tree = new int[m + 1];
            int[] res = new int[n];
            for (int j = 0; j < n; j++) {
                int idx = rev ? n - 1 - j : j;
                int r = Arrays.binarySearch(vals, 0, m, arr[idx][0]);
                res[idx] = qry(r);
                upd(r + 1, arr[idx][1]);
            }
            return res;
        };
        int[] left = calc(pr, false);
        int[] right = calc(pr, true);
        int ans = -1;
        for (int j = 0; j < n; j++)
            if (left[j] > 0 && right[j] > 0) ans = Math.max(ans, left[j] + profits[j] + right[j]);
        return ans;
    }
}

