var maxProfit = function(prices, profits) {
    const n = profits.length;
    const vals = [...new Set(prices)].sort((a, b) => a - b);
    const m = vals.length;
    const rk = (p) => lowerBound(vals, p) + 1;
    function lowerBound(a, x) { let lo = 0, hi = a.length; while (lo < hi) { const md = (lo + hi) >> 1; if (a[md] < x) lo = md + 1; else hi = md; } return lo; }
    const calc = (ps, fs) => {
        const tree = new Array(m + 1).fill(0), res = new Array(n).fill(0);
        const upd = (i, v) => { for (; i <= m; i += i & -i) tree[i] = Math.max(tree[i], v); };
        const qry = (i) => { let r = 0; for (; i > 0; i -= i & -i) r = Math.max(r, tree[i]); return r; };
        for (let j = 0; j < n; j++) {
            res[j] = qry(rk(ps[j]) - 1);
            upd(rk(ps[j]), fs[j]);
        }
        return res;
    };
    const left = calc(prices, profits);
    const right = calc([...prices].reverse(), [...profits].reverse()).reverse();
    let ans = -1;
    for (let j = 0; j < n; j++)
        if (left[j] > 0 && right[j] > 0) ans = Math.max(ans, left[j] + profits[j] + right[j]);
    return ans;
};
